class View:
    def __init__(self):
        self.rows=[]; self.notes={}; self.loading=False; self.error=None; self.seq=0
        self.lock = threading.Lock()
    def begin(self, query):
        with self.lock:
            self.seq+=1
            return self.seq
    def finish(self, request_id, rows):
        with self.lock:
            if request_id == self.seq and not self.loading:
                self.rows = rows
                self.loading = False
                self.error = None
                return True
            return False
